sys_script_include.script:
var TodoListFetcher = Class.create();
TodoListFetcher.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getLists: function() {
        try {
            var rm = new sn_ws.RESTMessageV2('x_1534869_todo_i_0.Todo Lists API', 'Get Todo Lists');

            var response = rm.execute();
            var statusCode = response.getStatusCode();

            if (statusCode === 200) {
                return response.getBody();
            } else {
                gs.error("Todo API failed with status code: " + statusCode);
                return null;
            }
        } catch (ex) {
            gs.error("Todo API Exception: " + ex.getMessage());
            return null;
        }
    },

    type: 'TodoListFetcher'
});
